class Solution:
    def circularArrayLoop(self, nums: list[int]) -> bool:
        for start in range(len(nums)):
            positive = nums[start] > 0
            seen = {}
            index = start
            while (nums[index] > 0) == positive:
                if index in seen:
                    if len(seen) - seen[index] > 1:
                        return True
                    break
                seen[index] = len(seen)
                index = (index + nums[index]) % len(nums)
        return False
